export function linkifyText(
  text: string,
  matcher: GlossaryMatcher,
  depth = 0,
  excludeTermId?: string,
): GlossarySegment[] {
  if (!text) return [{ text }];

  // Process explicit tags at any depth so bracket syntax does not leak as raw
  // "[...]" at depth >= MAX_DEPTH (e.g. "[shaken][g-condition]" flushes
  // to plain "shaken"), but preserve linked segments at depth 0 where
  // authors expect explicit tags to resolve against the glossary.
  const explicit = scanExplicitTags(text, matcher, excludeTermId);
  if (explicit.hadExplicit) {
    return explicit.segments.length
      ? depth >= MAX_DEPTH
        ? explicit.segments.map(s => ({ text: s.text }))
        : explicit.segments
      : [{ text: '' }];
  }

  // Skip auto-linking at or past MAX_DEPTH.  Depth 0 = top-level text (links);
  // depth 1 = inside a bubble (plain).  Explicit tags are handled above.
  if (depth >= MAX_DEPTH) return [{ text }];

  if (!matcher.regex) return [{ text }];

  const segments: GlossarySegment[] = [];
  let lastIndex = 0;
  matcher.regex.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = matcher.regex.exec(text))) {
    if (match.index > lastIndex) segments.push({ text: text.slice(lastIndex, match.index) });
    const term = matcher.termByKey.get(match[0].toLowerCase());
    // Excluded (a term's own name inside its own Definition) still renders as plain text —
    // only the tap-link is suppressed, the word itself must not disappear from the sentence.
    segments.push(term && term.Id !== excludeTermId ? { text: match[0], term } : { text: match[0] });
    lastIndex = match.index + match[0].length;
  }
  if (lastIndex < text.length) segments.push({ text: text.slice(lastIndex) });
  return segments.length ? segments : [{ text }];
}

